import pandas as pd
import numpy as np
import base64
import io
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import seaborn as sns
from pathlib import Path

# ─── Configuration ────────────────────────────────────────────────────────────
DATA_PATH = "/app/benchmark/data.csv"
OUTPUT_PATH = "/app/output/final_report.html"
PROFESSIONAL_THRESHOLD = 5  # hosts with >= 5 listings

COLORS = {
    "primary": "#1B3A5C",
    "accent": "#D4A843",
    "bg": "#F7F8FA",
    "card_bg": "#FFFFFF",
    "text": "#2C3E50",
    "muted": "#7F8C8D",
    "border": "#E0E4E8",
    "positive": "#27AE60",
    "negative": "#E74C3C",
    "chart_palette": [
        "#1B3A5C", "#D4A843", "#2E86AB", "#A23B72", "#F18F01",
        "#C73E1D", "#3B1F2B", "#44BBA4", "#E94F37", "#393E41"
    ],
}

CITY_ORDER = [
    "New York", "London", "Paris", "Tokyo", "Barcelona",
    "Los Angeles", "Amsterdam", "Bangkok", "Rome", "Sydney"
]

# ─── Load & Clean ─────────────────────────────────────────────────────────────
df = pd.read_csv(DATA_PATH)
df["price"] = pd.to_numeric(df["price"], errors="coerce")
df["reviews_per_month"] = pd.to_numeric(df["reviews_per_month"], errors="coerce")
df["availability_365"] = pd.to_numeric(df["availability_365"], errors="coerce")
df["calculated_host_listings_count"] = pd.to_numeric(df["calculated_host_listings_count"], errors="coerce")
df["minimum_nights"] = pd.to_numeric(df["minimum_nights"], errors="coerce")
df["number_of_reviews"] = pd.to_numeric(df["number_of_reviews"], errors="coerce")
df["number_of_reviews_ltm"] = pd.to_numeric(df["number_of_reviews_ltm"], errors="coerce")

# Price: remove extreme outliers for stats (keep within 1-99th percentile per city)
price_valid = df[df["price"].notna() & (df["price"] > 0)].copy()

# ─── KPI Computation ──────────────────────────────────────────────────────────
cities = df["city"].unique().tolist()
cities = [c for c in CITY_ORDER if c in cities] + [c for c in cities if c not in CITY_ORDER]

# 1. Median Nightly Price by City
median_price = price_valid.groupby("city")["price"].median().reindex(cities)

# 2. Average Nightly Price by City
mean_price = price_valid.groupby("city")["price"].mean().reindex(cities)

# 3. Professional Host Share
df["is_professional"] = df["calculated_host_listings_count"] >= PROFESSIONAL_THRESHOLD
prof_share = df.groupby("city")["is_professional"].mean().reindex(cities) * 100

# 4. Average Reviews per Month
avg_rpm = df.groupby("city")["reviews_per_month"].mean().reindex(cities)

# 5. Mean Availability
mean_avail = df.groupby("city")["availability_365"].mean().reindex(cities)

# 6. Entire Home Share
df["is_entire_home"] = df["room_type"] == "Entire home/apt"
entire_home_share = df.groupby("city")["is_entire_home"].mean().reindex(cities) * 100

# 7. Listing count per city
listing_counts = df.groupby("city").size().reindex(cities)

# 8. Room type breakdown
room_type_counts = df.groupby(["city", "room_type"]).size().unstack(fill_value=0).reindex(cities)
room_type_pct = room_type_counts.div(room_type_counts.sum(axis=1), axis=0) * 100

# 9. Price by room type
price_by_room = price_valid.groupby(["city", "room_type"])["price"].median().unstack().reindex(cities)

# 10. Price dispersion (IQR)
price_iqr = price_valid.groupby("city")["price"].agg(
    lambda x: x.quantile(0.75) - x.quantile(0.25)
).reindex(cities)

# 11. Reviews LTM
avg_reviews_ltm = df.groupby("city")["number_of_reviews_ltm"].mean().reindex(cities)

# 12. Min nights median
median_min_nights = df.groupby("city")["minimum_nights"].median().reindex(cities)

# 13. Last review recency (median days since last review from scrape date)
df["last_review_dt"] = pd.to_datetime(df["last_review"], errors="coerce")
df["scrape_date_dt"] = pd.to_datetime(df["scrape_date"], errors="coerce")
df["days_since_last_review"] = (df["scrape_date_dt"] - df["last_review_dt"]).dt.days
median_days_since_review = df.groupby("city")["days_since_last_review"].median().reindex(cities)

# 14. Host count
host_counts = df.groupby("city")["host_id"].nunique().reindex(cities)

# 15. Listings per host
listings_per_host = (listing_counts / host_counts).reindex(cities)

# ─── Chart Generation ─────────────────────────────────────────────────────────
sns.set_style("whitegrid")
plt.rcParams.update({
    "font.family": "DejaVu Sans",
    "font.size": 11,
    "axes.titlesize": 14,
    "axes.labelsize": 12,
    "figure.facecolor": COLORS["bg"],
    "axes.facecolor": COLORS["card_bg"],
    "text.color": COLORS["text"],
    "axes.edgecolor": COLORS["border"],
})

def fig_to_base64(fig, dpi=150):
    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=dpi, bbox_inches="tight", facecolor=fig.get_facecolor())
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode("utf-8")
    plt.close(fig)
    return b64

# ─── Chart 1: Median Price by City (Horizontal Bar) ──────────────────────────
fig1, ax1 = plt.subplots(figsize=(10, 6))
sorted_idx = median_price.sort_values().index
colors_bar = [COLORS["chart_palette"][CITY_ORDER.index(c)] if c in CITY_ORDER else "#888" for c in sorted_idx]
bars = ax1.barh(range(len(sorted_idx)), median_price[sorted_idx].values, color=colors_bar, edgecolor="white", height=0.65)
ax1.set_yticks(range(len(sorted_idx)))
ax1.set_yticklabels(sorted_idx, fontsize=11)
ax1.set_xlabel("Median Nightly Price (USD)", fontsize=12)
ax1.set_title("Median Nightly Price by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, (val, city) in enumerate(zip(median_price[sorted_idx].values, sorted_idx)):
    ax1.text(val + 2, i, f"${val:.0f}", va="center", fontsize=10, fontweight="bold", color=COLORS["text"])
ax1.spines["top"].set_visible(False)
ax1.spines["right"].set_visible(False)
chart1_b64 = fig_to_base64(fig1)

# ─── Chart 2: Room Type Distribution (Stacked Bar) ──────────────────────────
fig2, ax2 = plt.subplots(figsize=(11, 6))
room_types = ["Entire home/apt", "Private room", "Shared room", "Hotel room"]
room_types_present = [rt for rt in room_types if rt in room_type_pct.columns]
palette_rt = {"Entire home/apt": COLORS["primary"], "Private room": COLORS["accent"],
              "Shared room": "#7F8C8D", "Hotel room": "#2E86AB"}
bottom = np.zeros(len(cities))
for rt in room_types_present:
    vals = room_type_pct[rt].reindex(cities).fillna(0).values
    ax2.bar(range(len(cities)), vals, bottom=bottom, label=rt,
            color=palette_rt.get(rt, "#888"), edgecolor="white", width=0.65)
    bottom += vals
ax2.set_xticks(range(len(cities)))
ax2.set_xticklabels(cities, rotation=35, ha="right", fontsize=10)
ax2.set_ylabel("Share of Listings (%)", fontsize=12)
ax2.set_title("Room Type Distribution by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
ax2.legend(loc="upper right", frameon=True, fontsize=10)
ax2.spines["top"].set_visible(False)
ax2.spines["right"].set_visible(False)
chart2_b64 = fig_to_base64(fig2)

# ─── Chart 3: Professional Host Share ────────────────────────────────────────
fig3, ax3 = plt.subplots(figsize=(10, 6))
sorted_prof = prof_share.sort_values(ascending=False)
colors_prof = [COLORS["chart_palette"][CITY_ORDER.index(c)] if c in CITY_ORDER else "#888" for c in sorted_prof.index]
bars3 = ax3.bar(range(len(sorted_prof)), sorted_prof.values, color=colors_prof, edgecolor="white", width=0.65)
ax3.set_xticks(range(len(sorted_prof)))
ax3.set_xticklabels(sorted_prof.index, rotation=35, ha="right", fontsize=10)
ax3.set_ylabel("Share of Listings (%)", fontsize=12)
ax3.set_title("Professional Host Share (≥5 Listings)", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_prof.values):
    ax3.text(i, val + 0.8, f"{val:.1f}%", ha="center", fontsize=10, fontweight="bold", color=COLORS["text"])
ax3.spines["top"].set_visible(False)
ax3.spines["right"].set_visible(False)
chart3_b64 = fig_to_base64(fig3)

# ─── Chart 4: Median Price by Room Type (Grouped Bar) ───────────────────────
fig4, ax4 = plt.subplots(figsize=(12, 6))
x = np.arange(len(cities))
width = 0.18
room_types_chart = [rt for rt in room_types if rt in price_by_room.columns]
for i, rt in enumerate(room_types_chart):
    vals = price_by_room[rt].reindex(cities).values
    ax4.bar(x + i * width, vals, width, label=rt, color=palette_rt.get(rt, "#888"), edgecolor="white")
ax4.set_xticks(x + width * len(room_types_chart) / 2)
ax4.set_xticklabels(cities, rotation=35, ha="right", fontsize=10)
ax4.set_ylabel("Median Nightly Price (USD)", fontsize=12)
ax4.set_title("Median Nightly Price by City & Room Type", fontsize=15, fontweight="bold", color=COLORS["primary"])
ax4.legend(loc="upper right", frameon=True, fontsize=10)
ax4.spines["top"].set_visible(False)
ax4.spines["right"].set_visible(False)
chart4_b64 = fig_to_base64(fig4)

# ─── Chart 5: Average Reviews per Month ──────────────────────────────────────
fig5, ax5 = plt.subplots(figsize=(10, 6))
sorted_rpm = avg_rpm.sort_values(ascending=False)
colors_rpm = [COLORS["chart_palette"][CITY_ORDER.index(c)] if c in CITY_ORDER else "#888" for c in sorted_rpm.index]
ax5.bar(range(len(sorted_rpm)), sorted_rpm.values, color=colors_rpm, edgecolor="white", width=0.65)
ax5.set_xticks(range(len(sorted_rpm)))
ax5.set_xticklabels(sorted_rpm.index, rotation=35, ha="right", fontsize=10)
ax5.set_ylabel("Avg Reviews per Month", fontsize=12)
ax5.set_title("Average Reviews per Month by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_rpm.values):
    ax5.text(i, val + 0.02, f"{val:.2f}", ha="center", fontsize=9, fontweight="bold", color=COLORS["text"])
ax5.spines["top"].set_visible(False)
ax5.spines["right"].set_visible(False)
chart5_b64 = fig_to_base64(fig5)

# ─── Chart 6: Mean Availability ──────────────────────────────────────────────
fig6, ax6 = plt.subplots(figsize=(10, 6))
sorted_avail = mean_avail.sort_values(ascending=False)
colors_avail = [COLORS["chart_palette"][CITY_ORDER.index(c)] if c in CITY_ORDER else "#888" for c in sorted_avail.index]
ax6.bar(range(len(sorted_avail)), sorted_avail.values, color=colors_avail, edgecolor="white", width=0.65)
ax6.set_xticks(range(len(sorted_avail)))
ax6.set_xticklabels(sorted_avail.index, rotation=35, ha="right", fontsize=10)
ax6.set_ylabel("Mean Availability (days/year)", fontsize=12)
ax6.set_title("Mean Annual Availability by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_avail.values):
    ax6.text(i, val + 3, f"{val:.0f}", ha="center", fontsize=9, fontweight="bold", color=COLORS["text"])
ax6.spines["top"].set_visible(False)
ax6.spines["right"].set_visible(False)
chart6_b64 = fig_to_base64(fig6)

# ─── Chart 7: Price IQR (Dispersion) ─────────────────────────────────────────
fig7, ax7 = plt.subplots(figsize=(10, 6))
sorted_iqr = price_iqr.sort_values(ascending=False)
colors_iqr = [COLORS["chart_palette"][CITY_ORDER.index(c)] if c in CITY_ORDER else "#888" for c in sorted_iqr.index]
ax7.bar(range(len(sorted_iqr)), sorted_iqr.values, color=colors_iqr, edgecolor="white", width=0.65)
ax7.set_xticks(range(len(sorted_iqr)))
ax7.set_xticklabels(sorted_iqr.index, rotation=35, ha="right", fontsize=10)
ax7.set_ylabel("Interquartile Range (USD)", fontsize=12)
ax7.set_title("Price Dispersion (IQR) by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_iqr.values):
    ax7.text(i, val + 2, f"${val:.0f}", ha="center", fontsize=9, fontweight="bold", color=COLORS["text"])
ax7.spines["top"].set_visible(False)
ax7.spines["right"].set_visible(False)
chart7_b64 = fig_to_base64(fig7)

# ─── Chart 8: Median Minimum Nights ──────────────────────────────────────────
fig8, ax8 = plt.subplots(figsize=(10, 6))
sorted_mn = median_min_nights.sort_values(ascending=False)
colors_mn = [COLORS["chart_palette"][CITY_ORDER.index(c)] if c in CITY_ORDER else "#888" for c in sorted_mn.index]
ax8.bar(range(len(sorted_mn)), sorted_mn.values, color=colors_mn, edgecolor="white", width=0.65)
ax8.set_xticks(range(len(sorted_mn)))
ax8.set_xticklabels(sorted_mn.index, rotation=35, ha="right", fontsize=10)
ax8.set_ylabel("Median Minimum Nights", fontsize=12)
ax8.set_title("Median Minimum Night Stay by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_mn.values):
    ax8.text(i, val + 0.3, f"{val:.0f}", ha="center", fontsize=10, fontweight="bold", color=COLORS["text"])
ax8.spines["top"].set_visible(False)
ax8.spines["right"].set_visible(False)
chart8_b64 = fig_to_base64(fig8)

# ─── Compute Key Rankings ────────────────────────────────────────────────────
most_expensive = median_price.idxmax()
least_expensive = median_price.idxmin()
highest_prof = prof_share.idxmax()
lowest_prof = prof_share.idxmin()
highest_entire_home = entire_home_share.idxmax()
lowest_entire_home = entire_home_share.idxmin()
highest_rpm = avg_rpm.idxmax()
highest_avail = mean_avail.idxmax()

# ─── Build HTML ───────────────────────────────────────────────────────────────
def fmt(v, decimals=0, prefix="$", suffix=""):
    if pd.isna(v):
        return "N/A"
    return f"{prefix}{v:.{decimals}f}{suffix}"

def fmt_pct(v, decimals=1):
    if pd.isna(v):
        return "N/A"
    return f"{v:.{decimals}f}%"

def fmt_num(v, decimals=0):
    if pd.isna(v):
        return "N/A"
    return f"{v:,.{decimals}f}"

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Airbnb Cross-Market Analysis</title>
<style>
  :root {{
    --primary: {COLORS["primary"]};
    --accent: {COLORS["accent"]};
    --bg: {COLORS["bg"]};
    --card: {COLORS["card_bg"]};
    --text: {COLORS["text"]};
    --muted: {COLORS["muted"]};
    --border: {COLORS["border"]};
    --positive: {COLORS["positive"]};
    --negative: {COLORS["negative"]};
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, Oxygen, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}
  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 24px; }}
  header {{
    background: linear-gradient(135deg, var(--primary) 0%, #2C5F8A 100%);
    color: white;
    padding: 48px 0 40px;
    text-align: center;
  }}
  header h1 {{ font-size: 2.2rem; font-weight: 700; margin-bottom: 8px; letter-spacing: -0.5px; }}
  header p {{ font-size: 1.05rem; opacity: 0.9; max-width: 700px; margin: 0 auto; }}
  .meta-bar {{
    background: rgba(255,255,255,0.1);
    display: inline-block;
    padding: 6px 18px;
    border-radius: 20px;
    font-size: 0.85rem;
    margin-top: 14px;
  }}
  section {{ margin: 40px 0; }}
  .card {{
    background: var(--card);
    border-radius: 12px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
    padding: 32px;
    margin-bottom: 28px;
    border: 1px solid var(--border);
  }}
  .card h2 {{
    font-size: 1.45rem;
    color: var(--primary);
    margin-bottom: 6px;
    font-weight: 700;
  }}
  .card .subtitle {{
    color: var(--muted);
    font-size: 0.92rem;
    margin-bottom: 20px;
