ax2.set_xticks(range(len(cities)))
ax2.set_xticklabels(cities, rotation=35, ha="right", fontsize=10)
ax2.set_ylabel("Share of Listings (%)", fontsize=12)
ax2.set_title("Room Type Distribution by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
ax2.legend(loc="upper right", frameon=True, fontsize=10)
ax2.spines["top"].set_visible(False)
ax2.spines["right"].set_visible(False)
chart2_b64 = fig_to_base64(fig2)

# ─── Chart 3: Professional Host Share ────────────────────────────────────────
fig3, ax3 = plt.subplots(figsize=(10, 6))
sorted_prof = prof_share.sort_values(ascending=False)
colors_prof = [COLORS["chart_palette"][CITY_ORDER.index(c)] if c in CITY_ORDER else "#888" for c in sorted_prof.index]
bars3 = ax3.bar(range(len(sorted_prof)), sorted_prof.values, color=colors_prof, edgecolor="white", width=0.65)
