45	df["number_of_reviews"] = pd.to_numeric(df["number_of_reviews"], errors="coerce")
46	df["number_of_reviews_ltm"] = pd.to_numeric(df["number_of_reviews_ltm"], errors="coerce")
47	
48	# Price: remove extreme outliers for stats (keep within 1-99th percentile per city)
49	price_valid = df[df["price"].notna() & (df["price"] > 0)].copy()
50	
51	# ─── KPI Computation ──────────────────────────────────────────────────────────
52	cities = df["city"].unique().tolist()
53	cities = [c for c in CITY_ORDER if c in cities] + [c for c in cities if c not in CITY_ORDER]
54	
55	# 1. Median Nightly Price by City
56	median_price = price_valid.groupby("city")["price"].median().reindex(cities)
57	
58	# 2. Average Nightly Price by City
59	mean_price = price_valid.groupby("city")["price"].mean().reindex(cities)
60	
61	# 3. Professional Host Share
62	df["is_professional"] = df["calculated_host_listings_count"] >= PROFESSIONAL_THRESHOLD
63	prof_share = df.groupby("city")["is_professional"].mean().reindex(cities) * 100
64	
65	# 4. Average Reviews per Month
66	avg_rpm = df.groupby("city")["reviews_per_month"].mean().reindex(cities)
67	
68	# 5. Mean Availability
69	mean_avail = df.groupby("city")["availability_365"].mean().reindex(cities)
70	
71	# 6. Entire Home Share
72	df["is_entire_home"] = df["room_type"] == "Entire home/apt"
73	entire_home_share = df.groupby("city")["is_entire_home"].mean().reindex(cities) * 100
74	
75	# 7. Listing count per city
76	listing_counts = df.groupby("city").size().reindex(cities)
77	
78	# 8. Room type breakdown
