ice_valid = df[df[\"price\"].notna() & (df[\"price\"] > 0)].copy()\n\n# ─── KPI Computation ──────────────────────────────────────────────────────────\ncities = df[\"city\"].unique().tolist()\ncities = [c for c in CITY_ORDER if c in cities] + [c for c in cities if c not in CITY_ORDER]\n\n# 1. Median Nightly Price by City\nmedian_price = price_valid.groupby(\"city\")[\"price\"].median().reindex(cities)\n\n# 2. Average Nightly Price by City\nmean_price = price_valid.groupby(\"city\")[\"price\"].mean().reindex(cities)\n\n# 3. Professional Host Share\ndf[\"is_professional\"] = df[\"calculated_host_listings_count\"] >= PROFESSIONAL_THRESHOLD\nprof_share = df.groupby(\"city\")[\"is_professional\"].mean().reindex(cities) * 100\n\n# 4. Average Reviews per Month\navg_rpm = df.groupby(\"city\")[\"reviews_per_month\"].mean().reindex(cities)\n\n# 5. Mean Availability\nmean_avail = df.groupby(\"city\")[\"availability_365\"].mean().reindex(cities)\n\n# 6. Entire Home Share\ndf[\"is_entire_home\"] = df[\"room_type\"] == \"Entire home/apt\"\nentire_home_share = df.groupby(\"city\")[\"is_entire_home\"].mean().reindex(cities) * 100\n\n# 7. Listing count per city\nlisting_counts = df.groupby(\"city\").size().reindex(cities)\n\n# 8. Room type breakdown\nroom_type_counts = df.groupby([\"city\", \"room_type\"]).size().unstack(fill_value=0).reindex(cities)\nroom_type_pct = room_type_counts.div(room_type_counts.sum(axis=1), axis=0) * 100\n\n# 9. Price by room type\nprice_by_room = price_valid.groupby([\"city\", \"room_type\"])[\"price\"].median().unstack().reindex(cities)\n\n# 10. Price dispersion (IQR)\nprice_iqr = price_valid.groupby(\"city\")[\"price\"].agg(\n    lambda x: x.quantile(0.75) - x.quantile(0.25)\n).reindex(cities)\n\n# 11. Reviews LTM\navg_reviews_ltm = df.groupby(\"city\")[\"number_of_reviews_ltm\"].mean().reindex(cities)\n\n# 12. Min nights median\nmedian_min_nights = df.groupby(\"city\")[\"minimum_nights\"].median().reindex(cities)\n\n# 13. Last review recency (median days since last review from scrape date)\ndf[\"last_review_dt\"] = pd.to_datetime(df[\"last_review\"], errors=\"coerce\")\ndf[\"scrape_date_dt\"] = pd.to_datetime(df[\"scrape_date\"], errors=\"coerce\")\ndf[\"days_since_last_review\"] = (df[\"scrape_date_dt\"] - df[\"last_review_dt\"]).dt.days\nmedian_days_since_review = df.groupby(\"city\")[\"days_since_last_review\"].median().reindex(cities)\n\n# 14. Host count\nhost_counts = df.groupby(\"city\")[\"host_id\"].nunique().reindex(cities)\n\n# 15. Listings per host\nlistings_per_host = (listing_counts / host_counts).reindex(cities)\n\n# ─── Chart Generation ─────────────────────────────────────────────────────────\nsns.set_style(\"whitegrid\")\nplt.rcParams.update({\n    \"font.family\": \"DejaVu Sans\",\n    \"font.size\": 11,\n    \"axes.titlesize\": 14,\n    \"axes.labelsize\": 12,\n    \"figure.facecolor\": COLORS[\"bg\"],\n    \"axes.facecolor\": COLORS[\"card_bg\"],\n    \"text.color\": COLORS[\"text\"],\n    \"axes.edgecolor\": COLORS[\"border\"],\n})\n\ndef fig_to_base64(fig, dpi=150):\n    buf = io.BytesIO()\n    fig.savefig(buf, format=\"png\", dpi=dpi, bbox_inches=\"tight\", facecolor=fig.get_facecolor())\n    buf.seek(0)\n    b64 = base64.b64encode(buf.read()).decode(\"utf-8\")\n    plt.close(fig)\n    return b64\n\n# ─── Chart 1: Median Price by City (Horizontal Bar) ──────────────────────────\nfig1, ax1 = plt.subplots(figsize=(10, 6))\nsorted_idx = median_price.sort_values().index\ncolors_bar = [COLORS[\"chart_palette\"][CITY_ORDER.index(c)] if c in CITY_ORDER else \"#888\" for c in sorted_idx]\nbars = ax1.barh(range(len(sorted_idx)), median_price[sorted_idx].values, color=colors_bar, edgecolor=\"white\", height=0.65)\nax1.set_yticks(range(len(sorted_idx)))\nax1.set_yticklabels(sorted_idx, fontsize=11)\nax1.set_xlabel(\"Median Nightly Price (USD)\", fontsize=12)\nax1.set_title(\"Median Nightly Price by City\", fontsize=15, fontweight=\"bold\", color=COLORS[\"primary\"])\nfor i, (val, city) in enumerate(zip(median_price[sorted_idx].values, sorted_idx)):\n    ax1.text(val + 2, i, f\"${val:.0f}\", va=\"center\", fontsize=10, fontweight=\"bold\", color=COLORS[\"text\"])\nax1.spines[\"top\"].set_visible(False)\nax1.spines[\"right\"].set_visible(False)\nchart1_b64 = fig_to_base64(fig1)\n\n# ─── Chart 2: Room Type Distribution (Stacked Bar) ──────────────────────────\nfig2, ax2 = plt.subplots(figsize=(11, 6))\nroom_types = [\"Entire home/apt\", \"Private room\", \"Shared room\", \"Hotel room\"]\nroom_types_present = [rt for rt in room_types if rt in room_type_pct.columns]\npalette_rt = {\"Entire home/apt\": COLORS[\"primary\"], \"Private room\": COLORS[\"accent\"],\n              \"Shared room\": \"#7F8C8D\", \"Hotel room\": \"#2E86AB\"}\nbottom = np.zeros(len(cities))\nfor rt in room_types_present:\n    vals = room_type_pct[rt].reindex(cities).fillna(0).values\n    ax2.bar(range(len(cities)), vals, bottom=bottom, label=rt,\n            color=palette_rt.get(rt, \"#888\"), edgecolor=\"white\", width=0.65)\n    bottom += vals\nax2.set_xticks(range(len(cities)))\nax2.set_xticklabels(cities, rotation=35, ha=\"right\", fontsize=10)\nax2.set_ylabel(\"Share of Listings (%)\", fontsize=12)\nax2.set_title(\"Room Type Distribution by City\", fontsize=15, fontweight=\"bold\", color=COLORS[\"primary\"])\nax2.legend(loc=\"upper right\", frameon=True, fontsize=10)\nax2.spines[\"top\"].set_visible(False)\nax2.spines[\"right\"].set_visible(False)\nchart2_b64 = fig_to_base64(fig2)\n\n# ─── Chart 3: Professional Host Share ────────────────────────────────────────\nfig3, ax3 = plt.subplots(figsize=(10, 6))\nsorted_prof = prof_share.sort_values(ascending=False)\ncolors_prof = [COLORS[\"chart_palette\"][CITY_ORDER.index(c)] if c in CITY_ORDER else \"#888\" for c in sorted_prof.index]\nbars3 = ax3.bar(range(len(sorted_prof)), sorted_prof.values, color=colors_prof, edgecolor=\"white\", width=0.65)\nax3.set_xticks(range(len(sorted_prof)))\nax3.set_xticklabels(sorted_prof.index, rotation=35, ha=\"right\", fontsize=10)\nax3.set_ylabel(\"Share of Listings (%)\", fontsize=12)\nax3.set_title(\"Professional Host Share (≥5 Listings)\", fontsize=15, fontweight=\"bold\", color=COLORS[\"primary\"])\nfor i, val in enumerate(sorted_prof.values):\n    ax3.text(i, val + 0.8, f\"{val:.1f}%\", ha=\"center\", fontsize=10, fontweight=\"bold\", color=COLORS[\"text\"])\nax3.spines[\"top\"].set_visible(False)\nax3.spines[\"right\"].set_visible(False)\nchart3_b64 = fig_to_base64(fig3)\n\n# ─── Chart 4: Median Price by Room Type (Grouped Bar) ───────────────────────\nfig4, ax4 = plt.subplots(figsize=(12, 6))\nx = np.arange(len(cities))\nwidth = 0.18\nroom_types_chart = [rt for rt in room_types if rt in price_by_room.columns]\nfor i, rt in enumerate(room_types_chart):\n    vals = price_by_room[rt].reindex(cities).values\n    ax4.bar(x + i * width, vals, width, label=rt, color=palette_rt.get(rt, \"#888\"), edgecolor=\"white\")\nax4.set_xticks(x + width * len(room_types_chart) / 2)\nax4.set_xticklabels(cities, rotation=35, ha=\"right\", fontsize=10)\nax4.set_ylabel(\"Median Nightly Price (USD)\", fontsize=12)\nax4.set_title(\"Median Nightly Price by City & Room Type\", fontsize=15, fontweight=\"bold\", color=COLORS[\"primary\"])\nax4.legend(loc=\"upper right\", frameon=True, fontsize=10)\nax4.spines[\"top\"].set_visible(False)\nax4.spines[\"right\"].set_visible(False)\nchart4_b64 = fig_to_base64(fig4)\n\n# ─── Chart 5: Average Reviews per Month ──────────────────────────────────────\nfig5, ax5 = plt.subplots(figsize=(10, 6))\nsorted_rpm = avg_rpm.sort_values(ascending=False)\ncolors_rpm = [COLORS[\"chart_palette\"][CITY_ORDER.index(c)] if c in CITY_ORDER else \"#888\" for c in sorted_rpm.index]\nax5.bar(range(len(sorted_rpm)), sorted_rpm.values, color=colors_rpm, edgecolor=\"white\", width=0.65)\nax5.set_xticks(range(len(sorted_rpm)))\nax5.set_xticklabels(sorted_rpm.index, rotation=35, ha=\"right\", fontsize=10)\nax5.set_ylabel(\"Avg Reviews per Month\", fontsize=12)\nax5.set_title(\"Average Reviews per Month by City\", fontsize=15, fontweight=\"bold\", color=COLORS[\"primary\"])\nfor i, val in enumerate(sorted_rpm.values):\n    ax5.text(i, val + 0.02, f\"{val:.2f}\", ha=\"center\", fontsize=9, fontweight=\"bold\", color=COLORS[\"text\"])\nax5.spines[\"top\"].set_visible(False)\nax5.spines[\"right\"].set_visible(False)\nchart5_b64 = fig_to_base64(fig5)\n\n# ─── Chart 6: Mean Availability ──────────────────────────────────────────────\nfig6, ax6 = plt.subplots(figsize=(10, 6))\nsorted_avail = mean_avail.sort_values(ascending=False)\ncolors_avail = [COLORS[\"chart_palette\"][CITY_ORDER.index(c)] if c in CITY_ORDER else \"#888\" for c in sorted_avail.index]\nax6.bar(range(len(sorted_avail)), sorted_avail.values, color=colors_avail, edgecolor=\"white\", width=0.65)\nax6.set_xticks(range(len(sorted_avail)))\nax6.set_xticklabels(sorted_avail.index, rotation=35, ha=\"right\", fontsize=10)\nax6.set_ylabel(\"Mean Availability (days/year)\", fontsize=12)\nax6.set_title(\"Mean Annual Availability by City\", fontsize=15, fontweight=\"bold\", color=COLORS[\"primary\"])\nfor i, val in enumerate(sorted_avail.values):\n    ax6.text(i, val + 3, f\"{val:.0f}\", ha=\"center\", fontsize=9, fontweight=\"bold\", color=COLORS[\"text\"])\nax6.spines[\"top\"].set_visible(False)\nax6.spines[\"right\"].set_visible(False)\nchart6_b64 = fig_to_base64(fig6)\n\n# ─── Chart 7: Price IQR (Dispersion) ─────────────────────────────────────────\nfig7, ax7 = plt.subplots(figsize=(10, 6))\nsorted_iqr = price_iqr.sort_values(ascending=False)\ncolors_iqr = [COLORS[\"chart_palette\"][CITY_ORDER.index(c)] if c in CITY_ORDER else \"#888\" for c in sorted_iqr.index]\nax7.bar(range(len(sorted_iqr)), sorted_iqr.values, color=colors_iqr, edgecolor=\"white\", width=0.65)\nax7.set_xticks(range(len(sorted_iqr)))\nax7.set_xticklabels(sorted_iqr.index, rotation=35, ha=\"right\", fontsize=10)\nax7.set_ylabel(\"Interquartile Range (USD)\", fontsize=12)\nax7.set_title(\"Price Dispersion (IQR) by City\", fontsize=15, fontweight=\"bold\", color=COLORS[\"primary\"])\nfor i, val in enumerate(sorted_iqr.values):\n    ax7.text(i, val + 2, f\"${val:.0f}\", ha=\"center\", fontsize=9, fontweight=\"bold\", color=COLORS[\"text\"])\nax7.spines[\"top\"].set_visible(False)\nax7.spines[\"right\"].set_visible(False)\nchart7_b64 = fig_to_base64(fig7)\n\n# ─── Chart 8: Median Minimum Nights ──────────────────────────────────────────\nfig8, ax8 = plt.subplots(figsize=(10, 6))\nsorted_mn = median_min_nights.sort_values(ascending=False)\ncolors_mn = [COLORS[\"chart_palette\"][CITY_ORDER.index(c)] if c in CITY_ORDER else \"#888\" for c in sorted_mn.index]\nax8.bar(range(len(sorted_mn)), sorted_mn.values, color=colors_mn, edgecolor=\"white\", width=0.65)\nax8.set_xticks(range(len(sorted_mn)))\nax8.set_xticklabels(sorted_mn.index, rotation=35, ha=\"right\", fontsize=10)\nax8.set_ylabel(\"Median Minimum Nights\", fontsize=12)\nax8.set_title(\"Median Minimum Night Stay by City\", fontsize=15, fontweight=\"bold\", color=COLORS[\"primary\"])\nfor i, val in enumerate(sorted_mn.values):\n    ax8.text(i, val + 0.3, f\"{val:.0f}\", ha=\"center\", fontsize=10, fontweight=\"bold\", color=COLORS[\"text\"])\nax8.spines[\"top\"].set_visible(False)\nax8.spines[\"right\"].set_visible(False)\nchart8_b64 = fig_to_base64(fig8)\n\n# ─── Compute Key Rankings ────────────────────────────────────────────────────\nmost_expensive = median_price.idxmax()\nleast_expensive = median_price.idxmin()\nhighest_prof = prof_share.idxmax()\nlowest_prof = prof_share.idxmin()\nhighest_entire_home = entire_home_share.idxmax()\nlowest_entire_home = entire_home_share.idxmin()\nhighest_rpm = avg_rpm.idxmax()\nhighest_avail = mean_avail.idxmax()\n\n# ─── Build HTML ───────────────────────────────────────────────────────────────\ndef fmt(v, decimals=0, prefix=\"$\", suffix=\"\"):\n    if pd.isna(v):\n        return \"N/A\"\n    return f\"{prefix}{v:.{decimals}f}{suffix}\"\n\ndef fmt_pct(v, decimals=1):\n    if pd.isna(v):\n        return \"N/A\"\n    return f\"{v:.{decimals}f}%\"\n\ndef fmt_num(v, decimals=0):\n    if pd.isna(v):\n        return \"N/A\"\n    return f\"{v:,.{decimals}f}\"\n\nhtml = f\"\"\"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Global Airbnb Cross-Market Analysis</title>\n<style>\n  :root {{\n    --primary: {COLORS[\"primary\"]};\n    --accent: {COLORS[\"accent\"]};\n    --bg: {COLORS[\"bg\"]};\n    --card: {COLORS[\"card_bg\"]};\n    --text: {COLORS[\"text\"]};\n    --muted: {COLORS[\"muted\"]};\n    --border: {COLORS[\"border\"]};\n    --positive: {COLORS[\"positive\"]};\n    --negative: {COLORS[\"negative\"]};\n  }}\n  * {{ margin: 0; padding: 0; box-sizing: border-box; }}\n  body {{\n    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, Oxygen, sans-serif;\n    background: var(--bg);\n    color: var(--text);\n    line-height: 1.6;\n  }}\n  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 24px; }}\n  header {{\n    background: linear-gradient(135deg, var(--primary) 0%, #2C5F8A 100%);\n    color: white;\n    padding: 48px 0 40px;\n    text-align: center;\n  }}\n  header h1 {{ font-size: 2.2rem; font-weight: 700; margin-bottom: 8px; letter-spacing: -0.5px; }}\n  header p {{ font-size: 1.05rem; opacity: 0.9; max-width: 700px; margin: 0 auto; }}\n  .meta-bar {{\n    background: rgba(255,255,255,0.1);\n    display: inline-block;\n    padding: 6px 18px;\n    border-radius: 20px;\n    font-size: 0.85rem;\n    margin-top: 14px;\n  }}\n  section {{ margin: 40px 0; }}\n  .card {{\n    background: var(--card);\n    border-radius: 12px;\n    box-shadow: 0 2px 12px rgba(0,0,0,0.06);\n    padding: 32px;\n    margin-bottom: 28px;\n    border: 1px solid var(--border);\n  }}\n  .card h2 {{\n    font-size: 1.45rem;\n    color: var(--primary);\n    margin-bottom: 6px;\n    font-weight: 700;\n  }}\n  .card .subtitle {{\n    color: var(--muted);\n    font-size: 0.92rem;\n    margin-bottom: 20px;\n  }}\n  .kpi-grid {{\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));\n    gap: 16px;\n    margin-bottom: 20px;\n  }}\n  .kpi-box {{\n    background: var(--bg);\n    border-radius: 10px;\n    padding: 18px 16px;\n    text-align: center;\n    border: 1px solid var(--border);\n  }}\n  .kpi-box .kpi-value {{\n    font-size: 1.6rem;\n    font-weight: 700;\n    color: var(--primary);\n  }}\n  .kpi-box .kpi-label {{\n    font-size: 0.78rem;\n    color: var(--muted);\n    margin-top: 4px;\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n  }}\n  .chart-img {{\n    width: 100%;\n    max-width: 100%;\n    border-radius: 8px;\n    margin: 12px 0;\n  }}\n  table {{\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 0.9rem;\n    margin: 16px 0;\n  }}\n  th {{\n    background: var(--primary);\n    color: white;\n    padding: 10px 12px;\n    text-align: left;\n    font-weight: 600;\n    font-size: 0.82rem;\n    text-transform: uppercase;\n    letter-spacing: 0.4px;\n  }}\n  th:first-child {{ border-radius: 8px 0 0 0; }}\n  th:last-child {{ border-radius: 0 8px 0 0; }}\n  td {{\n    padding: 10px 12px;\n    border-bottom: 1px solid var(--border);\n  }}\n  tr:nth-child(even) td {{ background: #F9FAFB; }}\n  tr:hover td {{ background: #EEF2F7; }}\n  .highlight {{ color: var(--accent); font-weight: 700; }}\n  .takeaway {{\n    background: linear-gradient(135deg, #F0F4F8 0%, #E8EDF2 100%);\n    border-left: 4px solid var(--accent);\n    padding: 14px 18px;\n    margin: 10px 0;\n    border-radius: 0 8px 8px 0;\n    font-size: 0.95rem;\n  }}\n  .takeaway strong {{ color: var(--primary); }}\n  .section-divider {{\n    height: 3px;\n    background: linear-gradient(90deg, var(--primary), var(--accent));\n    border: none;\n    margin: 48px 0;\n    border-radius: 2px;\n    opacity: 0.3;\n  }}\n  footer {{\n    text-align: center;\n    padding: 32px 0;\n    color: var(--muted);\n    font-size: 0.82rem;\n    border-top: 1px solid var(--border);\n    margin-top: 40px;\n  }}\n  .data-note {{\n    background: #FFF8E7;\n    border: 1px solid #F0D78C;\n    border-radius: 8px;\n    padding: 12px 16px;\n    font-size: 0.85rem;\n    color: #7A6B2E;\n    margin: 12px 0;\n  }}\n</style>\n</head>\n<body>\n\n<header>\n  <div class=\"container\">\n    <h1>Global Airbnb Cross-Market Analysis</h1>\n    <p>Pricing, Supply & Guest Demand Across 10 Major Cities</p>\n    <div class=\"meta-bar\">\n      {fmt_num(len(df))} Listings &nbsp;|&nbsp; 10 Cities &nbsp;|&nbsp; Data as of March 2026\n    </div>\n  </div>\n</header>\n\n<div class=\"container\">\n\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<!-- SECTION 1: GLOBAL MARKET OVERVIEW                                      -->\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<section id=\"market-overview\">\n  <div class=\"card\">\n    <h2>1. Global Market Overview</h2>\n    <p class=\"subtitle\">Total listings, price distribution, and room-type breakdown across all 10 markets.</p>\n\n    <div class=\"kpi-grid\">\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt_num(len(df))}</div>\n        <div class=\"kpi-label\">Total Listings</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt_num(df['host_id'].nunique())}</div>\n        <div class=\"kpi-label\">Unique Hosts</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt(median_price.mean(), 0)}</div>\n        <div class=\"kpi-label\">Cross-City Median Price</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt_pct(entire_home_share.mean(), 1)}</div>\n        <div class=\"kpi-label\">Avg Entire-Home Share</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt_pct(prof_share.mean(), 1)}</div>\n        <div class=\"kpi-label\">Avg Professional Host Share</div>\n      </div>\n    </div>\n\n    <table>\n      <thead>\n        <tr>\n          <th>City</th>\n          <th>Listings</th>\n          <th>Unique Hosts</th>\n          <th>Median Price</th>\n          <th>Mean Price</th>\n          <th>Entire Home %</th>\n          <th>Prof. Host %</th>\n        </tr>\n      </thead>\n      <tbody>\n\"\"\"\n\nfor c in cities:\n    html += f\"\"\"        <tr>\n          <td><strong>{c}</strong></td>\n          <td>{fmt_num(listing_counts[c])}</td>\n          <td>{fmt_num(host_counts[c])}</td>\n          <td>{fmt(median_price[c])}</td>\n          <td>{fmt(mean_price[c])}</td>\n          <td>{fmt_pct(entire_home_share[c])}</td>\n          <td>{fmt_pct(prof_share[c])}</td>\n        </tr>\n\"\"\"\n\nhtml += f\"\"\"      </tbody>\n    </table>\n\n    <div class=\"data-note\">\n      <strong>Data Note:</strong> Price statistics exclude listings with missing or zero prices. {price_valid['price'].isna().sum() + (price_valid['price'] == 0).sum()} listings with missing/zero prices were excluded from price calculations. Professional hosts defined as those with ≥5 listings.\n    </div>\n  </div>\n</section>\n\n<hr class=\"section-divider\">\n\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<!-- SECTION 2: PRICING DYNAMICS                                            -->\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<section id=\"pricing-analysis\">\n  <div class=\"card\">\n    <h2>2. Pricing Dynamics Across Cities</h2>\n    <p class=\"subtitle\">Median and average nightly prices by city and room type. The most and least expensive markets, and price dispersion within each city.</p>\n\n    <div class=\"kpi-grid\">\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\" style=\"color: var(--positive);\">{most_expensive}</div>\n        <div class=\"kpi-label\">Most Expensive (Median)</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt(median_price[most_expensive])}</div>\n        <div class=\"kpi-label\">Median Price</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\" style=\"color: var(--negative);\">{least_expensive}</div>\n        <div class=\"kpi-label\">Least Expensive (Median)</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt(median_price[least_expensive])}</div>\n        <div class=\"kpi-label\">Median Price</div>\n      </div>\n    </div>\n\n    <img class=\"chart-img\" src=\"data:image/png;base64,{chart1_b64}\" alt=\"Median Nightly Price by City\">\n\n    <h3 style=\"margin-top:28px; color:var(--primary);\">Price by City & Room Type</h3>\n    <img class=\"chart-img\" src=\"data:image/png;base64,{chart4_b64}\" alt=\"Median Price by City and Room Type\">\n\n    <h3 style=\"margin-top:28px; color:var(--primary);\">Price Dispersion (Interquartile Range)</h3>\n    <p class=\"subtitle\">Wider IQR indicates greater price variability — signaling a market with both budget and premium segments.</p>\n    <img class=\"chart-img\" src=\"data:image/png;base64,{chart7_b64}\" alt=\"Price Dispersion IQR by City\">\n\n    <table>\n      <thead>\n        <tr>\n          <th>City</th>\n          <th>Median Price</th>\n          <th>Mean Price</th>\n          <th>IQR (Q3−Q1)</th>\n          <th>Price Range Signal</th>\n        </tr>\n      </thead>\n      <tbody>\n\"\"\"\n\nfor c in cities:\n    iqr_val = price_iqr[c]\n    signal = \"Low\" if iqr_val < price_iqr.median() else \"High\"\n    signal_color = \"var(--positive)\" if signal == \"Low\" else \"var(--accent)\"\n    html += f\"\"\"        <tr>\n          <td><strong>{c}</strong></td>\n          <td>{fmt(median_price[c])}</td>\n          <td>{fmt(mean_price[c])}</td>\n          <td>{fmt(price_iqr[c])}</td>\n          <td style=\"color:{signal_color}; font-weight:600;\">{signal} dispersion</td>\n        </tr>\n\"\"\"\n\nhtml += f\"\"\"      </tbody>\n    </table>\n  </div>\n</section>\n\n<hr class=\"section-divider\">\n\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<!-- SECTION 3: SUPPLY STRUCTURE & HOST CONCENTRATION                       -->\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<section id=\"supply-structure\">\n  <div class=\"card\">\n    <h2>3. Supply Structure & Host Concentration</h2>\n    <p class=\"subtitle\">Room-type distribution, professional vs. individual host prevalence, and host concentration metrics.</p>\n\n    <h3 style=\"color:var(--primary); margin-bottom:8px;\">Room Type Distribution</h3>\n    <img class=\"chart-img\" src=\"data:image/png;base64,{chart2_b64}\" alt=\"Room Type Distribution by City\">\n\n    <h3 style=\"margin-top:28px; color:var(--primary); margin-bottom:8px;\">Professional Host Concentration</h3>\n    <p class=\"subtitle\">Listings where the host operates 5+ properties, indicating commercial-scale operations.</p>\n    <img class=\"chart-img\" src=\"data:image/png;base64,{chart3_b64}\" alt=\"Professional Host Share by City\">\n\n    <div class=\"kpi-grid\" style=\"margin-top:20px;\">\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{highest_prof}</div>\n        <div class=\"kpi-label\">Highest Prof. Host Share</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt_pct(prof_share[highest_prof])}</div>\n        <div class=\"kpi-label\">Share</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{lowest_prof}</div>\n        <div class=\"kpi-label\">Lowest Prof. Host Share</div>\n      </div>\n      <div class=\"kpi-box\">\n        <div class=\"kpi-value\">{fmt_pct(prof_share[lowest_prof])}</div>\n        <div class=\"kpi-label\">Share</div>\n      </div>\n    </div>\n\n    <table>\n      <thead>\n        <tr>\n          <th>City</th>\n          <th>Entire Home %</th>\n          <th>Private Room %</th>\n          <th>Shared Room %</th>\n          <th>Hotel Room %</th>\n          <th>Prof. Host %</th>\n          <th>Avg Listings/Host</th>\n        </tr>\n      </thead>\n      <tbody>\n\"\"\"\n\nfor c in cities:\n    eh = entire_home_share[c]\n    pr = room_type_pct.get(\"Private room\", pd.Series(dtype=float)).reindex([c]).values[0] if \"Private room\" in room_type_pct.columns else 0\n    sr = room_type_pct.get(\"Shared room\", pd.Series(dtype=float)).reindex([c]).values[0] if \"Shared room\" in room_type_pct.columns else 0\n    hr = room_type_pct.get(\"Hotel room\", pd.Series(dtype=float)).reindex([c]).values[0] if \"Hotel room\" in room_type_pct.columns else 0\n    html += f\"\"\"        <tr>\n          <td><strong>{c}</strong></td>\n          <td>{fmt_pct(eh)}</td>\n          <td>{fmt_pct(pr)}</td>\n          <td>{fmt_pct(sr)}</td>\n          <td>{fmt_pct(hr)}</td>\n          <td>{fmt_pct(prof_share[c])}</td>\n          <td>{listings_per_host[c]:.2f}</td>\n        </tr>\n\"\"\"\n\nhtml += f\"\"\"      </tbody>\n    </table>\n  </div>\n</section>\n\n<hr class=\"section-divider\">\n\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<!-- SECTION 4: GUEST DEMAND & REVIEW ACTIVITY                              -->\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<section id=\"guest-demand\">\n  <div class=\"card\">\n    <h2>4. Guest Demand & Review Activity</h2>\n    <p class=\"subtitle\">Review-based demand proxies across cities: reviews per month, reviews in the last 12 months, and review recency.</p>\n\n    <img class=\"chart-img\" src=\"data:image/png;base64,{chart5_b64}\" alt=\"Average Reviews per Month by City\">\n\n    <table>\n      <thead>\n        <tr>\n          <th>City</th>\n          <th>Avg Reviews/Month</th>\n          <th>Avg Reviews (LTM)</th>\n          <th>Median Days Since Last Review</th>\n          <th>Demand Signal</th>\n        </tr>\n      </thead>\n      <tbody>\n\"\"\"\n\nrpm_median = avg_rpm.median()\nfor c in cities:\n    demand = \"Strong\" if avg_rpm[c] >= rpm_median else \"Moderate\"\n    demand_color = \"var(--positive)\" if demand == \"Strong\" else \"var(--muted)\"\n    html += f\"\"\"        <tr>\n          <td><strong>{c}</strong></td>\n          <td>{avg_rpm[c]:.2f}</td>\n          <td>{avg_reviews_ltm[c]:.1f}</td>\n          <td>{fmt_num(median_days_since_review[c])}</td>\n          <td style=\"color:{demand_color}; font-weight:600;\">{demand}</td>\n        </tr>\n\"\"\"\n\nhtml += f\"\"\"      </tbody>\n    </table>\n\n    <div class=\"data-note\">\n      <strong>Methodology Note:</strong> Reviews per month and LTM review counts serve as proxies for booking frequency, not direct measures. A listing may be booked frequently without receiving reviews, and review rates vary by culture and platform. Listings with zero reviews are included in city averages (contributing 0 to LTM, NaN excluded from RPM mean).\n    </div>\n  </div>\n</section>\n\n<hr class=\"section-divider\">\n\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<!-- SECTION 5: AVAILABILITY & BOOKING CONSTRAINTS                          -->\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<section id=\"availability-minimumnights\">\n  <div class=\"card\">\n    <h2>5. Availability & Booking Constraints</h2>\n    <p class=\"subtitle\">Annual availability and minimum-night requirements — indicators of commercial intent and regulatory impact.</p>\n\n    <img class=\"chart-img\" src=\"data:image/png;base64,{chart6_b64}\" alt=\"Mean Annual Availability by City\">\n\n    <h3 style=\"margin-top:28px; color:var(--primary); margin-bottom:8px;\">Minimum Night Requirements</h3>\n    <p class=\"subtitle\">High minimum-night thresholds often reflect local short-term rental regulations restricting nightly stays.</p>\n    <img class=\"chart-img\" src=\"data:image/png;base64,{chart8_b64}\" alt=\"Median Minimum Nights by City\">\n\n    <table>\n      <thead>\n        <tr>\n          <th>City</th>\n          <th>Mean Availability (days/yr)</th>\n          <th>Median Min. Nights</th>\n          <th>Regulatory Signal</th>\n        </tr>\n      </thead>\n      <tbody>\n\"\"\"\n\nfor c in cities:\n    avail = mean_avail[c]\n    mn = median_min_nights[c]\n    if mn >= 30:\n        reg_signal = \"Restrictive (likely STR regulation)\"\n        reg_color = \"var(--negative)\"\n    elif mn >= 7:\n        reg_signal = \"Moderate constraints\"\n        reg_color = \"var(--accent)\"\n    else:\n        reg_signal = \"Flexible / permissive\"\n        reg_color = \"var(--positive)\"\n    html += f\"\"\"        <tr>\n          <td><strong>{c}</strong></td>\n          <td>{avail:.0f}</td>\n          <td>{mn:.0f}</td>\n          <td style=\"color:{reg_color}; font-weight:600;\">{reg_signal}</td>\n        </tr>\n\"\"\"\n\nhtml += f\"\"\"      </tbody>\n    </table>\n  </div>\n</section>\n\n<hr class=\"section-divider\">\n\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<!-- SECTION 6: KEY TAKEAWAYS & STRATEGIC IMPLICATIONS                      -->\n<!-- ═══════════════════════════════════════════════════════════════════════ -->\n<section id=\"key-takeaways\">\n  <div class=\"card\">\n    <h2>6. Key Takeaways & Strategic Implications</h2>\n    <p class=\"subtitle\">Actionable insights for investors, hosts, and policymakers, derived from the data above.</p>\n\"\"\"\n\n# Compute insights programmatically\nprice_spread = median_price.max() / median_price.min()\ntop3_prof = prof_share.nlargest(3)\nbot3_prof = prof_share.nsmallest(3)\ntop3_entire = entire_home_share.nlargest(3)\n\nhtml += f\"\"\"\n    <div class=\"takeaway\">\n      <strong>1. Pricing varies {price_spread:.1f}x across markets.</strong> {most_expensive} commands a median of {fmt(median_price[most_expensive])}/night — {price_spread:.1f}x the median in {least_expensive} ({fmt(median_price[least_expensive])}). This gap reflects both local purchasing power and regulatory environments. For investors, {least_expensive} offers lower barriers to entry but tighter margins; {most_expensive} demands more capital but supports premium positioning.\n    </div>\n\n    <div class=\"takeaway\">\n      <strong>2. Professional hosts dominate in {top3_prof.index[0]} ({fmt_pct(top3_prof.values[0])}), {top3_prof.index[1]} ({fmt_pct(top3_prof.values[1])}), and {top3_prof.index[2]} ({fmt_pct(top3_prof.values[2])}).</strong> These markets are heavily commercialized — new entrants face established multi-listing operators. In contrast, {bot3_prof.index[0]} ({fmt_pct(bot3_prof.values[0])}) remains fragmented, offering better conditions for independent hosts to gain visibility.\n    </div>\n\n    <div class=\"takeaway\">\n      <strong>3. Entire-home dominance signals commercialization.</strong> {top3_entire.index[0]} ({fmt_pct(top3_entire.values[0])}), {top3_entire.index[1]} ({fmt_pct(top3_entire.values[1])}), and {top3_entire.index[2]} ({fmt_pct(top3_entire.values[2])}) have the highest entire-home shares. Markets where entire-home listings predominate tend to have more professional operators and face greater regulatory scrutiny — policymakers often target entire-home listings when tightening STR rules.\n    </div>\n\n    <div class=\"takeaway\">\n      <strong>4. {highest_rpm} leads in review activity (avg {avg_rpm[highest_rpm]:.2f} reviews/month),</strong> indicating strong and recurring guest demand. High review frequency combined with high availability suggests a mature, high-throughput market. Cities with lower review rates may represent underpenetrated markets or ones where guests book through alternative channels.\n    </div>\n\n    <div class=\"takeaway\">\n      <strong>5. Minimum-night requirements reveal regulatory regimes.</strong> {median_min_nights.idxmax()} (median {median_min_nights.max():.0f} nights) and cities with median stays above 30 nights likely enforce strict short-term rental caps. {median_min_nights.idxmin()} (median {median_min_nights.min():.0f} nights) offers the most flexible booking environment. Regulatory risk is highest in cities with the most restrictive minimum-night regimes — they may further tighten rules.\n    </div>\n\n    <div class=\"takeaway\">\n      <strong>6. Availability gaps signal market maturity vs. regulation.</strong> {highest_avail} averages {mean_avail[highest_avail]:.0f} available days/year, suggesting commercially-oriented listings operating near full capacity. Cities with very low average availability may indicate either strong booking occupancy or listings pulled from the market due to regulatory compliance actions.\n    </div>\n  </div>\n</section>\n\n</div>\n\n<footer>\n  <div class=\"container\">\n    <p>Global Airbnb Cross-Market Analysis &nbsp;|&nbsp; Data: Inside Airbnb (CC BY 4.0) &nbsp;|&nbsp; Report generated May 2026</p>\n    <p style=\"margin-top:4px;\">Prices normalized to USD equivalent. All statistics derived from {fmt_num(len(df))} listings across 10 cities.</p>\n  </div>\n</footer>\n\n</body>\n</html>\n\"\"\"\n\n# ─── Write Output ─────────────────────────────────────────────────────────────\nPath(OUTPUT_PATH).parent.mkdir(parents=True, exist_ok=True)\nwith open(OUTPUT_PATH, \"w\", encoding=\"utf-8\") as f:\n    f.write(html)\n\nprint(f\"Report written to {OUTPUT_PATH}\")\nprint(f\"File size: {Path(OUTPUT_PATH).stat().st_size / 1024:.1f} KB\")\n", "numLines": 823, "startLine": 1, "totalLines": 823}}

