import pandas as pd
import numpy as np
import base64
import io
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import seaborn as sns
from pathlib import Path

# ─── Configuration ────────────────────────────────────────────────────────────
DATA_PATH = "/app/benchmark/data.csv"
OUTPUT_PATH = "/app/output/final_report.html"
PROFESSIONAL_THRESHOLD = 5  # hosts with >= 5 listings

COLORS = {
    "primary": "#1B3A5C",
    "accent": "#D4A843",
    "bg": "#F7F8FA",
    "card_bg": "#FFFFFF",
    "text": "#2C3E50",
    "muted": "#7F8C8D",
    "border": "#E0E4E8",
    "positive": "#27AE60",
    "negative": "#E74C3C",
    "chart_palette": [
        "#1B3A5C", "#D4A843", "#2E86AB", "#A23B72", "#F18F01",
        "#C73E1D", "#3B1F2B", "#44BBA4", "#E94F37", "#393E41"
    ],
}

CITY_ORDER = [
    "New York", "London", "Paris", "Tokyo", "Barcelona",
    "Los Angeles", "Amsterdam", "Bangkok", "Rome", "Sydney"
]

# ─── Load & Clean ─────────────────────────────────────────────────────────────
df = pd.read_csv(DATA_PATH)
df["price"] = pd.to_numeric(df["price"], errors="coerce")
df["reviews_per_month"] = pd.to_numeric(df["reviews_per_month"], errors="coerce")
df["availability_365"] = pd.to_numeric(df["availability_365"], errors="coerce")
df["calculated_host_listings_count"] = pd.to_numeric(df["calculated_host_listings_count"], errors="coerce")
df["minimum_nights"] = pd.to_numeric(df["minimum_nights"], errors="coerce")
df["number_of_reviews"] = pd.to_numeric(df["number_of_reviews"], errors="coerce")
df["number_of_reviews_ltm"] = pd.to_numeric(df["number_of_reviews_ltm"], errors="coerce")

# Price: remove extreme outliers for stats (keep within 1-99th percentile per city)
price_valid = df[df["price"].notna() & (df["price"] > 0)].copy()

# ─── KPI Computation ──────────────────────────────────────────────────────────
cities = df["city"].unique().tolist()
cities = [c for c in CITY_ORDER if c in cities] + [c for c in cities if c not in CITY_ORDER]

# 1. Median Nightly Price by City
median_price = price_valid.groupby("city")["price"].median().reindex(cities)

# 2. Average Nightly Price by City
mean_price = price_valid.groupby("city")["price"].mean().reindex(cities)

# 3. Professional Host Share
df["is_professional"] = df["calculated_host_listings_count"] >= PROFESSIONAL_THRESHOLD
prof_share = df.groupby("city")["is_professional"].mean().reindex(cities) * 100

# 4. Average Reviews per Month
avg_rpm = df.groupby("city")["reviews_per_month"].mean().reindex(cities)

# 5. Mean Availability
mean_avail = df.groupby("city")["availability_365"].mean().reindex(cities)

# 6. Entire Home Share
df["is_entire_home"] = df["room_type"] == "Entire home/apt"
entire_home_share = df.groupby("city")["is_entire_home"].mean().reindex(cities) * 100

# 7. Listing count per city
listing_counts = df.groupby("city").size().reindex(cities)

# 8. Room type breakdown
room_type_counts = df.groupby(["city", "room_type"]).size().unstack(fill_value=0).reindex(cities)
room_type_pct = room_type_counts.div(room_type_counts.sum(axis=1), axis=0) * 100

# 9. Price by room type
price_by_room = price_valid.groupby(["city", "room_type"])["price"].median().unstack().reindex(cities)

# 10. Price dispersion (IQR)
price_iqr = price_valid.groupby("city")["price"].agg(
    lambda x: x.quantile(0.75) - x.quantile(0.25)
).reindex(cities)

# 11. Reviews LTM
avg_reviews_ltm = df.groupby("city")["number_of_reviews_ltm"].mean().reindex(cities)

# 12. Min nights median
median_min_nights = df.groupby("city")["minimum_nights"].median().reindex(cities)

# 13. Last review recency (median days since last review from scrape date)
df["last_review_dt"] = pd.to_datetime(df["last_review"], errors="coerce")
df["scrape_date_dt"] = pd.to_datetime(df["scrape_date"], errors="coerce")
df["days_since_last_review"] = (df["scrape_date_dt"] - df["last_review_dt"]).dt.days
median_days_since_review = df.groupby("city")["days_since_last_review"].median().reindex(cities)

# 14. Host count
host_counts = df.groupby("city")["host_id"].nunique().reindex(cities)

# 15. Listings per host
listings_per_host = (listing_counts / host_counts).reindex(cities)

# ─── Chart Generation ─────────────────────────────────────────────────────────
