import pandas as pd
import numpy as np
import base64
import io
import warnings
warnings.filterwarnings("ignore")
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import seaborn as sns
from pathlib import Path

# ─── Configuration ────────────────────────────────────────────────────────────
DATA_PATH = "/app/benchmark/data.csv"
OUTPUT_PATH = "/app/output/final_report.html"
PROFESSIONAL_THRESHOLD = 5  # hosts with >= 5 listings

COLORS = {
    "primary": "#1B3A5C",
    "accent": "#D4A843",
    "bg": "#F7F8FA",
    "card_bg": "#FFFFFF",
    "text": "#2C3E50",
    "muted": "#7F8C8D",
    "border": "#E0E4E8",
    "positive": "#27AE60",
    "negative": "#E74C3C",
    "chart_palette": [
        "#1B3A5C", "#D4A843", "#2E86AB", "#A23B72", "#F18F01",
        "#C73E1D", "#3B1F2B", "#44BBA4", "#E94F37", "#393E41"
    ],
}

# ─── Load & Clean ─────────────────────────────────────────────────────────────
df = pd.read_csv(DATA_PATH)
df["price"] = pd.to_numeric(df["price"], errors="coerce")
df["reviews_per_month"] = pd.to_numeric(df["reviews_per_month"], errors="coerce")
df["availability_365"] = pd.to_numeric(df["availability_365"], errors="coerce")
df["calculated_host_listings_count"] = pd.to_numeric(df["calculated_host_listings_count"], errors="coerce")
df["minimum_nights"] = pd.to_numeric(df["minimum_nights"], errors="coerce")
df["number_of_reviews"] = pd.to_numeric(df["number_of_reviews"], errors="coerce")
df["number_of_reviews_ltm"] = pd.to_numeric(df["number_of_reviews_ltm"], errors="coerce")

# Identify which cities are present
all_cities_in_data = sorted(df["city"].unique())
EXPECTED_CITIES = ["New York", "London", "Paris", "Tokyo", "Barcelona",
                   "Los Angeles", "Amsterdam", "Bangkok", "Rome", "Sydney"]
missing_cities = [c for c in EXPECTED_CITIES if c not in all_cities_in_data]
present_cities = [c for c in EXPECTED_CITIES if c in all_cities_in_data]

# Use only present cities in display order
cities = present_cities + [c for c in all_cities_in_data if c not in present_cities]

# ─── Price Data Quality Assessment ────────────────────────────────────────────
price_null_rate = df.groupby("city")["price"].apply(lambda x: x.isna().mean() * 100)
# Cities with valid price data (non-null rate > 50%)
cities_with_price = price_null_rate[price_null_rate < 50].index.tolist()
# Cities with no price data at all
cities_no_price = price_null_rate[price_null_rate >= 50].index.tolist()

# Bangkok: prices appear to be in local currency (Thai Baht), not USD.
# Median ~1,400 THB ≈ ~$40 USD (approximate March 2026 rate).
# We flag Bangkok separately and exclude it from direct USD cross-city comparisons.
BANGKOK_THB_TO_USD = 1 / 35.0  # approximate rate

# For price analysis, only use cities with valid, USD-denominated price data
price_comparable_cities = [c for c in cities_with_price if c != "Bangkok"]

# Valid prices (non-null, > 0)
price_valid = df[df["price"].notna() & (df["price"] > 0)].copy()

# Convert Bangkok prices to approximate USD for comparison
price_valid_usd = price_valid.copy()
bk_mask = price_valid_usd["city"] == "Bangkok"
price_valid_usd.loc[bk_mask, "price_usd"] = price_valid_usd.loc[bk_mask, "price"] * BANGKOK_THB_TO_USD
other_mask = price_valid_usd["city"] != "Bangkok"
price_valid_usd.loc[other_mask, "price_usd"] = price_valid_usd.loc[other_mask, "price"]

# For price charts, use the USD-normalized data for all cities that have price data
cities_price_chart = cities_with_price  # Bangkok included with conversion note

# ─── KPI Computation ──────────────────────────────────────────────────────────

# Using raw price for city-level stats (separate Bangkok handling)
def compute_city_price_stats(pdf, city_list, price_col="price"):
    median_p = pdf.groupby("city")[price_col].median().reindex(city_list)
    mean_p = pdf.groupby("city")[price_col].mean().reindex(city_list)
    iqr_p = pdf.groupby("city")[price_col].agg(lambda x: x.quantile(0.75) - x.quantile(0.25)).reindex(city_list)
    return median_p, mean_p, iqr_p

# USD-normalized prices for all cities with price data
median_price_usd, mean_price_usd, iqr_price_usd = compute_city_price_stats(
    price_valid_usd, cities_with_price, "price_usd"
)

# Raw prices for non-Bangkok cities
median_price_raw, mean_price_raw, iqr_price_raw = compute_city_price_stats(
    price_valid[price_valid["city"] != "Bangkok"], price_comparable_cities, "price"
)

# Professional Host Share
df["is_professional"] = df["calculated_host_listings_count"] >= PROFESSIONAL_THRESHOLD
prof_share = df.groupby("city")["is_professional"].mean().reindex(cities) * 100

# Average Reviews per Month
avg_rpm = df.groupby("city")["reviews_per_month"].mean().reindex(cities)

# Mean Availability
mean_avail = df.groupby("city")["availability_365"].mean().reindex(cities)

# Entire Home Share
df["is_entire_home"] = df["room_type"] == "Entire home/apt"
entire_home_share = df.groupby("city")["is_entire_home"].mean().reindex(cities) * 100

# Listing count per city
listing_counts = df.groupby("city").size().reindex(cities)

# Room type breakdown
room_type_counts = df.groupby(["city", "room_type"]).size().unstack(fill_value=0).reindex(cities)
room_type_pct = room_type_counts.div(room_type_counts.sum(axis=1), axis=0) * 100

# Price by room type (USD-normalized for cities with price data)
price_by_room_usd = price_valid_usd.groupby(["city", "room_type"])["price_usd"].median().unstack().reindex(cities_with_price)

# Reviews LTM
avg_reviews_ltm = df.groupby("city")["number_of_reviews_ltm"].mean().reindex(cities)

# Min nights median
median_min_nights = df.groupby("city")["minimum_nights"].median().reindex(cities)

# Last review recency
df["last_review_dt"] = pd.to_datetime(df["last_review"], errors="coerce")
df["scrape_date_dt"] = pd.to_datetime(df["scrape_date"], errors="coerce")
df["days_since_last_review"] = (df["scrape_date_dt"] - df["last_review_dt"]).dt.days
median_days_since_review = df.groupby("city")["days_since_last_review"].median().reindex(cities)

# Host count
host_counts = df.groupby("city")["host_id"].nunique().reindex(cities)

# Listings per host
listings_per_host = (listing_counts / host_counts).reindex(cities)

# ─── Chart Generation ─────────────────────────────────────────────────────────
sns.set_style("whitegrid")
plt.rcParams.update({
    "font.family": "DejaVu Sans",
    "font.size": 11,
    "axes.titlesize": 14,
    "axes.labelsize": 12,
    "figure.facecolor": COLORS["bg"],
    "axes.facecolor": COLORS["card_bg"],
    "text.color": COLORS["text"],
    "axes.edgecolor": COLORS["border"],
})

def fig_to_base64(fig, dpi=150):
    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=dpi, bbox_inches="tight", facecolor=fig.get_facecolor())
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode("utf-8")
    plt.close(fig)
    return b64

def city_color(c):
    return COLORS["chart_palette"][EXPECTED_CITIES.index(c)] if c in EXPECTED_CITIES else "#888"

# ─── Chart 1: Median Price by City (USD-normalized, horizontal bar) ──────────
fig1, ax1 = plt.subplots(figsize=(10, 5))
# Only plot cities that have price data
plot_cities_p = [c for c in cities_with_price if c in median_price_usd.index and not pd.isna(median_price_usd[c])]
sorted_p = median_price_usd[plot_cities_p].sort_values()
colors_bar = [city_color(c) for c in sorted_p.index]
bars = ax1.barh(range(len(sorted_p)), sorted_p.values, color=colors_bar, edgecolor="white", height=0.6)
ax1.set_yticks(range(len(sorted_p)))
labels = []
for c in sorted_p.index:
    lbl = c
    if c == "Bangkok":
        lbl = f"{c} (est. USD*)"
    labels.append(lbl)
ax1.set_yticklabels(labels, fontsize=11)
ax1.set_xlabel("Median Nightly Price (USD)", fontsize=12)
ax1.set_title("Median Nightly Price by City (USD-Equivalent)", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_p.values):
    ax1.text(val + 1, i, f"${val:.0f}", va="center", fontsize=10, fontweight="bold", color=COLORS["text"])
ax1.spines["top"].set_visible(False)
ax1.spines["right"].set_visible(False)
chart1_b64 = fig_to_base64(fig1)

# ─── Chart 2: Room Type Distribution (Stacked Bar) ──────────────────────────
fig2, ax2 = plt.subplots(figsize=(10, 6))
room_types = ["Entire home/apt", "Private room", "Shared room", "Hotel room"]
room_types_present = [rt for rt in room_types if rt in room_type_pct.columns]
palette_rt = {"Entire home/apt": COLORS["primary"], "Private room": COLORS["accent"],
              "Shared room": "#7F8C8D", "Hotel room": "#2E86AB"}
bottom = np.zeros(len(cities))
for rt in room_types_present:
    vals = room_type_pct[rt].reindex(cities).fillna(0).values
    ax2.bar(range(len(cities)), vals, bottom=bottom, label=rt,
            color=palette_rt.get(rt, "#888"), edgecolor="white", width=0.65)
    bottom += vals
ax2.set_xticks(range(len(cities)))
ax2.set_xticklabels(cities, rotation=35, ha="right", fontsize=10)
ax2.set_ylabel("Share of Listings (%)", fontsize=12)
ax2.set_title("Room Type Distribution by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
ax2.legend(loc="upper right", frameon=True, fontsize=10)
ax2.spines["top"].set_visible(False)
ax2.spines["right"].set_visible(False)
chart2_b64 = fig_to_base64(fig2)

# ─── Chart 3: Professional Host Share ────────────────────────────────────────
fig3, ax3 = plt.subplots(figsize=(10, 6))
sorted_prof = prof_share.sort_values(ascending=False)
colors_prof = [city_color(c) for c in sorted_prof.index]
bars3 = ax3.bar(range(len(sorted_prof)), sorted_prof.values, color=colors_prof, edgecolor="white", width=0.65)
ax3.set_xticks(range(len(sorted_prof)))
ax3.set_xticklabels(sorted_prof.index, rotation=35, ha="right", fontsize=10)
ax3.set_ylabel("Share of Listings (%)", fontsize=12)
ax3.set_title("Professional Host Share (≥5 Listings)", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_prof.values):
    ax3.text(i, val + 0.8, f"{val:.1f}%", ha="center", fontsize=10, fontweight="bold", color=COLORS["text"])
ax3.spines["top"].set_visible(False)
ax3.spines["right"].set_visible(False)
chart3_b64 = fig_to_base64(fig3)

# ─── Chart 4: Median Price by Room Type (Grouped Bar, USD-normalized) ───────
fig4, ax4 = plt.subplots(figsize=(11, 6))
chart_cities_p = [c for c in cities_with_price if c in price_by_room_usd.index]
x = np.arange(len(chart_cities_p))
width = 0.18
room_types_chart = [rt for rt in room_types if rt in price_by_room_usd.columns]
for i, rt in enumerate(room_types_chart):
    vals = price_by_room_usd[rt].reindex(chart_cities_p).values
    ax4.bar(x + i * width, vals, width, label=rt, color=palette_rt.get(rt, "#888"), edgecolor="white")
ax4.set_xticks(x + width * len(room_types_chart) / 2)
ax4.set_xticklabels(chart_cities_p, rotation=35, ha="right", fontsize=10)
ax4.set_ylabel("Median Nightly Price (USD)", fontsize=12)
ax4.set_title("Median Price by City & Room Type (USD-Equiv.)", fontsize=15, fontweight="bold", color=COLORS["primary"])
ax4.legend(loc="upper right", frameon=True, fontsize=10)
ax4.spines["top"].set_visible(False)
ax4.spines["right"].set_visible(False)
chart4_b64 = fig_to_base64(fig4)

# ─── Chart 5: Average Reviews per Month ──────────────────────────────────────
fig5, ax5 = plt.subplots(figsize=(10, 6))
sorted_rpm = avg_rpm.sort_values(ascending=False)
colors_rpm = [city_color(c) for c in sorted_rpm.index]
ax5.bar(range(len(sorted_rpm)), sorted_rpm.values, color=colors_rpm, edgecolor="white", width=0.65)
ax5.set_xticks(range(len(sorted_rpm)))
ax5.set_xticklabels(sorted_rpm.index, rotation=35, ha="right", fontsize=10)
ax5.set_ylabel("Avg Reviews per Month", fontsize=12)
ax5.set_title("Average Reviews per Month by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_rpm.values):
    ax5.text(i, val + 0.02, f"{val:.2f}", ha="center", fontsize=9, fontweight="bold", color=COLORS["text"])
ax5.spines["top"].set_visible(False)
ax5.spines["right"].set_visible(False)
chart5_b64 = fig_to_base64(fig5)

# ─── Chart 6: Mean Availability ──────────────────────────────────────────────
fig6, ax6 = plt.subplots(figsize=(10, 6))
sorted_avail = mean_avail.sort_values(ascending=False)
colors_avail = [city_color(c) for c in sorted_avail.index]
ax6.bar(range(len(sorted_avail)), sorted_avail.values, color=colors_avail, edgecolor="white", width=0.65)
ax6.set_xticks(range(len(sorted_avail)))
ax6.set_xticklabels(sorted_avail.index, rotation=35, ha="right", fontsize=10)
ax6.set_ylabel("Mean Availability (days/year)", fontsize=12)
ax6.set_title("Mean Annual Availability by City", fontsize=15, fontweight="bold", color=COLORS["primary"])
for i, val in enumerate(sorted_avail.values):
    ax6.text(i, val + 3, f"{val:.0f}", ha="center", fontsize=9, fontweight="bold", color=COLORS["text"])
ax6.spines["top"].set_visible(False)
ax6.spines["right"].set_visible(False)
chart6_b64 = fig_to_base64(fig6)

# ─── Chart 7: Price IQR (Dispersion, USD-normalized) ─────────────────────────
fig7, ax7 = plt.subplots(figsize=(10, 5))
plot_cities_iqr = [c for c in cities_with_price if c in iqr_price_usd.index and not pd.isna(iqr_price_usd[c])]
